class Solution {
public:
    int balancedString(std::string s) {
        std::unordered_map<char, int> count;
        for (char c : s) count[c]++;
        int n = s.size(), k = n / 4;
        if (count['Q'] <= k && count['W'] <= k && count['E'] <= k && count['R'] <= k) return 0;

        int ans = n, left = 0;
        for (int right = 0; right < n; ++right) {
            count[s[right]]--;
            while (count['Q'] <= k && count['W'] <= k && count['E'] <= k && count['R'] <= k) {
                ans = std::min(ans, right - left + 1);
                count[s[left++]]++;
            }
        }
        return ans;
    }
};

class Solution {
    public int balancedString(String s) {
        int[] count = new int[26];
        for (char c : s.toCharArray()) count[c - 'A']++;
        int n = s.length(), k = n / 4;
        if (count['Q' - 'A'] <= k && count['W' - 'A'] <= k && count['E' - 'A'] <= k && count['R' - 'A'] <= k) return 0;

        int ans = n, left = 0;
        for (int right = 0; right < n; right++) {
            count[s.charAt(right) - 'A']--;
            while (count['Q' - 'A'] <= k && count['W' - 'A'] <= k && count['E' - 'A'] <= k && count['R' - 'A'] <= k) {
                ans = Math.min(ans, right - left + 1);
                count[s.charAt(left++) - 'A']++;
            }
        }
        return ans;
    }
}

var balancedString = function(s) {
    const count = { Q: 0, W: 0, E: 0, R: 0 };
    for (const c of s) count[c]++;
    const n = s.length, k = n / 4;
    if (count.Q <= k && count.W <= k && count.E <= k && count.R <= k) return 0;

    let ans = n, left = 0;
    for (let right = 0; right < n; right++) {
        count[s[right]]--;
        while (count.Q <= k && count.W <= k && count.E <= k && count.R <= k) {
            ans = Math.min(ans, right - left + 1);
            count[s[left++]]++;
        }
    }
    return ans;
};
